   10 | export async function authMiddleware(c: Context, next: Next) {
   11 |   const authHeader = c.req.header("Authorization");
   12 |   if (!authHeader || !authHeader.startsWith("Bearer ")) {
   13 |     return c.json({ error: "Unauthorized" }, 401);
   14 |   }
   15 | 
   16 |   const token = authHeader.slice(7);
   17 |   try {
   18 |     const payload = await verify(token, JWT_SECRET, "HS256");
   19 |     c.set("userId", payload.userId as number);
   20 |     c.set("email", payload.email as string);
   21 |     await next();
   22 |   } catch {
   23 |     return c.json({ error: "Invalid or expired token" }, 401);
   24 |   }
   25 | }
